SELECT
    ,
    st.store_name AS storeName,
    u.nickname AS userName


    t.is_deleted = 0


        AND (t.coupon_name LIKE CONCAT('%', #{q.keyword}, '%')
        OR t.coupon_code LIKE CONCAT('%', #{q.keyword}, '%'))


        AND t.coupon_type = #{q.couponType}


        AND t.status = #{q.status}




        AND t.valid_start >= #{q.startFrom}


        AND t.valid_start <= #{q.startTo}



ORDER BY t.id DESC

