UPDATE shop_activity_coupon
SET issued_count = issued_count + #{count}
WHERE id = #{couponId}
  AND is_deleted = 0
  AND (total_count = 0 OR issued_count + #{count} <= total_count)

UPDATE shop_activity_coupon
SET used_count = used_count + #{count}
WHERE id = #{couponId}
  AND is_deleted = 0
  AND used_count + #{count} <= issued_count

UPDATE shop_activity_coupon
SET used_count = used_count - #{count}
WHERE id = #{couponId}
  AND is_deleted = 0
  AND used_count >= #{count}
